export const IKU_KANBAN_IMAGE_EXTENSIONS: ReadonlySet<string> = new Set([
  'png',
  'jpg',
  'jpeg',
  'gif',
  'webp',
  'svg',
  'bmp',
  'tiff',
  'avif',
  'ico',
  'heic',
  'heif',
]);
export function isIkuKanbanImageAttachment(attachment: {
  readonly filename: string;
  readonly mime: string | null;
  readonly localPath?: string | null;
}): boolean {
  if (attachment.localPath) return false;
  return (
    attachment.mime?.startsWith('image/') === true ||
    IKU_KANBAN_IMAGE_EXTENSIONS.has(attachment.filename.toLowerCase().split('.').pop() ?? '')
  );
}

hierarchy:
export type RelativeLocatorKey = string & { readonly __relativeLocatorKey: unique symbol };
export type RelativeLocatorScopeKey = '' | RelativeLocatorKey;

function fail(code: string): never {
  throw new Error(code);
}

export function parseRelativeLocatorKey(value: unknown): RelativeLocatorKey {
  if (typeof value !== 'string' || value.length === 0) {
    fail('RELATIVE_LOCATOR_KEY_INVALID');
  }
  if (value.includes('\0') || value.startsWith('/') || value.endsWith('/')) {
    fail('RELATIVE_LOCATOR_KEY_INVALID');
  }
  const segments = value.split('/');
  if (segments.some((segment) => segment.length === 0 || segment === '.' || segment === '..')) {
    fail('RELATIVE_LOCATOR_KEY_INVALID');
  }
  return value as RelativeLocatorKey;
}

export function parseRelativeLocatorScopeKey(value: unknown): RelativeLocatorScopeKey {
  return value === '' ? '' : parseRelativeLocatorKey(value);
}

