function hasAsciiControlCharacter(value: string): boolean {
  for (const character of value) {
    if (character.charCodeAt(0) < 32) return true;
  }
  return false;
}

methods:
async saveCover(record: IkuKanbanBodyRecord, id: string, filename: string, bytes: Uint8Array) {
  if (
    !/^[a-f0-9-]{36}$/iu.test(id) ||
    !filename ||
    /[\\/:*?"<>|]/u.test(filename) ||
    hasAsciiControlCharacter(filename) ||
    filename === '.' ||
    filename === '..'
  )
    throw new Error('KANBAN_COVER_FILENAME_INVALID');
  const folder = parseRelativeLocatorKey(
    `${record.bodyFolder ? `${record.bodyFolder}/` : ''}attachment/${id}`,
  );
  await ensureFolder(folder);
  const path = parseRelativeLocatorKey(`${folder}/${filename}`);
  return vault.createBinary(path, Uint8Array.from(bytes).buffer);
},
coverUrl(path: string | null | undefined) {
  if (!path) return null;
  const key = parseRelativeLocatorKey(path);
  const file = vault.getAbstractFileByPath(key);
  return file instanceof TFile ? vault.getResourcePath(file) : null;
},
